// Monitor de trials: 3 eventos idempotentes num unico statement.
// - inicio: relogio do teste comeca na PRIMEIRA mensagem do usuario
// - aviso5: 5 dias antes de vencer
// - fim: venceu -> suspende o acesso e junta o resumo de uso
// Avisos pro Thiago so entre 8h e 22h de Sao Paulo (webhook {force:true} ignora a janela).
let force = false;
try { const b = items[0].json.body || items[0].json; force = !!b.force; } catch (e) {}
if (!force) {
  const hora = parseInt(new Date().toLocaleString('sv-SE', { timeZone: 'America/Sao_Paulo' }).substring(11, 13), 10);
  if (hora < 8 || hora > 22) return [];
}
const sql = `WITH inicio AS (
  UPDATE giulia_donos d
  SET acesso_expira_em = NOW() + make_interval(days => d.trial_dias),
      relatorio_diario = TRUE
  WHERE d.trial_dias IS NOT NULL AND d.acesso_expira_em IS NULL AND d.status = 'ativo'
    AND EXISTS (SELECT 1 FROM giulia_memoria m WHERE m.from_numero = d.numero AND m.role = 'user')
  RETURNING d.numero, d.nome, d.nome_completo, d.trial_dias, d.acesso_expira_em
), aviso AS (
  UPDATE giulia_donos d SET trial_aviso_d5 = TRUE
  WHERE d.acesso_expira_em IS NOT NULL AND d.status = 'ativo' AND NOT d.trial_aviso_d5
    AND d.acesso_expira_em > NOW() AND d.acesso_expira_em < NOW() + INTERVAL '5 days'
    AND d.numero NOT IN (SELECT numero FROM inicio)
  RETURNING d.numero, d.nome, d.nome_completo, d.acesso_expira_em
), fim AS (
  UPDATE giulia_donos d SET status = 'suspenso'
  WHERE d.acesso_expira_em IS NOT NULL AND d.status = 'ativo' AND d.acesso_expira_em < NOW()
  RETURNING d.numero, d.nome, d.nome_completo, d.acesso_expira_em
)
SELECT 'inicio' AS evento, numero, nome, nome_completo,
       to_char(acesso_expira_em AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY') AS data_fim,
       trial_dias AS dias, NULL::int AS msgs, NULL::int AS gastos, NULL::int AS orcs, NULL::int AS lembs
FROM inicio
UNION ALL
SELECT 'aviso5', numero, nome, nome_completo,
       to_char(acesso_expira_em AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY'),
       CEIL(EXTRACT(EPOCH FROM acesso_expira_em - NOW()) / 86400)::int, NULL, NULL, NULL, NULL
FROM aviso
UNION ALL
SELECT 'fim', f.numero, f.nome, f.nome_completo,
       to_char(f.acesso_expira_em AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY'), NULL,
       (SELECT count(*)::int FROM giulia_memoria m WHERE m.from_numero = f.numero AND m.role = 'user'),
       (SELECT count(*)::int FROM giulia_gastos g WHERE g.dono_numero = f.numero),
       (SELECT count(*)::int FROM giulia_orcamentos o WHERE o.dono_numero = f.numero),
       (SELECT count(*)::int FROM giulia_lembretes l WHERE l.dono_numero = f.numero)
FROM fim f;`;
return [{ json: { sql } }];

// Um aviso pro Thiago por evento de trial
const THIAGO = '5511910441709';
const out = [];
for (const it of items) {
  const e = it.json;
  if (!e || !e.evento || !e.numero) continue;
  let texto;
  if (e.evento === 'inicio') {
    texto = `${e.nome_completo} comecou a usar o assistente hoje. O teste de ${e.dias} dias vai ate ${e.data_fim} - te aviso 5 dias antes de vencer.`;
  } else if (e.evento === 'aviso5') {
    texto = `O teste do ${e.nome_completo} vence em ${e.dias} dia${e.dias > 1 ? 's' : ''} (${e.data_fim}). Bom momento pra falar de renovacao com ele.`;
  } else {
    texto = `O teste do ${e.nome_completo} acabou (${e.data_fim}) e pausei o acesso dele. Uso no periodo: ${e.msgs} mensagens, ${e.gastos} gastos, ${e.orcs} orcamentos, ${e.lembs} lembretes. Pra renovar me fala: 'reativa o ${e.nome} por mais 30 dias' (ou sem prazo).`;
  }
  const esc = s => String(s == null ? '' : s).replace(/'/g, "''");
  out.push({ json: {
    number: THIAGO,
    texto,
    memoria_sql: "INSERT INTO giulia_memoria (role, content, from_numero) VALUES ('assistant', '" + esc(texto) + "', '" + THIAGO + "');"
  } });
}
return out;
